def _format_advisory_value(val: Any) -> str:
    match val:
        case str():
            return val.strip()
        case list():
            return _format_advisory_list(val)
        case dict():
            return _format_advisory_dict(val)
        case _:
            return ""


def _format_advisory_list(val: list) -> str:
    items = [_format_advisory_value(item) for item in val if item]
    return "\n".join(f"- {item}" for item in items if item)


def _format_advisory_dict(val: dict) -> str:
    sub_parts = []
    for k, v in val.items():
        formatted = _format_advisory_value(v)
        if formatted:
            sub_parts.append(f"{k.capitalize()}:\n{formatted}")
    return "\n\n".join(sub_parts)


class AdvisoryFallback:
    def __init__(self, advisory: Any, rationale: Any) -> None:
        self.advisory = advisory
        self.rationale = rationale

    def _get_fallback_narrative(self) -> str | None:
        result = _advisory_to_text(self.advisory)
        if result:
            return result
        return _rationale_to_text(self.rationale) or self._get_module_6a_content()

    def _get_module_6a_content(self) -> str | None:
        return None


def _advisory_to_text(advisory: Any) -> str | None:
    match advisory:
        case str() as text:
            if text.strip():
                return text.strip()
        case dict() as adict:
            parts = _format_advisory_dict(adict)
            if parts:
                return parts
    return None


def _rationale_to_text(rationale: Any) -> str | None:
    if isinstance(rationale, str) and rationale.strip():
        return rationale.strip()
    return None
